const PLACEHOLDER = /\{(\w+)\}/g;

// A `Message` handed as an argument (one resolved key placed inside another) is written as its
// text, as every target writes it; any other value as its string form.
function argumentText(value: unknown): string {
  return typeof value === 'object' && value !== null && Object.keys(value).length === 1 &&
    'text' in value && typeof value.text === 'string'
    ? value.text
    : String(value);
}

function interpolate(template: string, args: Readonly<Record<string, unknown>>): string {
  return template.replace(PLACEHOLDER, (fullMatch, name: string) =>
    name in args ? argumentText(args[name]) : fullMatch,
  );
}

/**
 * Whether *messageKey* resolves in *locale* or the catalog's default locale --
 * the test of a text that is optional, shown only when the catalog sets it.
 */
export function hasMessage(catalog: TextCatalog, locale: string, messageKey: string): boolean {
  const fallback = catalog.defaultLocale;
  return (
    catalog.pluralMessages[locale]?.[messageKey] !== undefined ||
    catalog.pluralMessages[fallback]?.[messageKey] !== undefined ||
    catalog.messages[locale]?.[messageKey] !== undefined ||
    catalog.messages[fallback]?.[messageKey] !== undefined
  );
}

/**
 * Resolve *messageKey* in *locale*, falling back to the catalog's default
 * locale. A key found in neither is a defect in the catalog -- it throws,
 * naming the key, rather than showing the raw key to a user.
 */
export function resolveMessage(
  catalog: TextCatalog,
  locale: string,
  messageKey: string,
  args: Readonly<Record<string, unknown>> = {},
): Message {
  const fallback = catalog.defaultLocale;
  const pluralEntry =
    catalog.pluralMessages[locale]?.[messageKey] ?? catalog.pluralMessages[fallback]?.[messageKey];
  if (pluralEntry !== undefined) {
    const count = Number(args[pluralEntry.selector]);
    const category = pluralCategory(count, locale);
    const template = pluralEntry.forms[category] ?? pluralEntry.forms['other'];
    if (template === undefined) {
      throw new Error(`Message '${messageKey}' has no '${category}' or 'other' plural form.`);
    }
    return { text: interpolate(template, args) };
  }
  const template = catalog.messages[locale]?.[messageKey] ?? catalog.messages[fallback]?.[messageKey];
  if (template === undefined) {
    throw new Error(`Message '${messageKey}' is not in the text catalog for '${locale}' or '${fallback}'.`);
  }
  return { text: interpolate(template, args) };
}

/** *catalog*'s messages in the locale *locale* reads, on every call. */
export class CatalogMessages implements FormMessages {
  private readonly catalog: TextCatalog;
  private readonly locale: () => string;

  constructor(catalog: TextCatalog, locale: () => string) {
    this.catalog = catalog;
    this.locale = locale;
  }

  has(messageKey: string): boolean {
    return hasMessage(this.catalog, this.locale(), messageKey);
  }

  key(messageKey: string, args: Readonly<Record<string, unknown>> = {}): Message {
    return resolveMessage(this.catalog, this.locale(), messageKey, args);
  }
}

/**
 * The text a form shows (`fieldErrorText`, `reviewText`, an `errorLabelKey`):
 * by default `FRAMEWORK_TEXT` in `CLIENT_LOCALE`. Provide it to show the
 * consumer's own text.
 */
export const FORM_MESSAGES = new InjectionToken<FormMessages>('FORM_MESSAGES', {
  providedIn: 'root',
  factory: () => new CatalogMessages(FRAMEWORK_TEXT, inject(CLIENT_LOCALE)),
});
